import { SheetPage } from '../../slots/defs/sheetPage';
import { usePeople } from '../people/people';
import { STATUSES, useSheetDueTotal, useSheetOverdue, useMyCrewDue, useMyFigures, useMyReviewsCount, useStatusCounts } from './totals';

/** The sheet's header counters, at the top of the sheet: its people (retired included), its claims per status
 *  (as the summary counts them), its due-total and overdue-total (as the rollups show them), and the signed-in user's
 *  own due-total and overdue-total (blank when no person on the sheet has the user's name or alias) and crew total
 *  (blank unless that person leads a crew), and how many REVIEW claims are assigned to the user for review. */
function Header({ sheetId, user }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId);
  const withStatus = useStatusCounts(sheetId);
  const dueTotal = useSheetDueTotal(sheetId);
  const overdue = useSheetOverdue(sheetId);
  const my = useMyFigures(sheetId, user);
  const myCrew = useMyCrewDue(sheetId, user);
  const myReviews = useMyReviewsCount(sheetId, user);

  return (
    <header data-testid="header">
      People <span data-testid="header-people-count">{(people.data ?? []).length}</span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}
          {s} <span data-testid={`header-claims-${s}-count`}>{withStatus(s)}</span>
        </span>
      ))}
      {' · '}Due total <span data-testid="header-due-total">{dueTotal}</span>
      {' · '}Overdue total <span data-testid="header-overdue-total">{overdue.total}</span>
      {' · '}My due total <span data-testid="my-due-total">{my?.due ?? ''}</span>
      {' · '}My overdue total <span data-testid="my-overdue-total">{my?.overdue ?? ''}</span>
      {' · '}My crew due total <span data-testid="my-crew-due-total">{myCrew ?? ''}</span>
      {' · '}My reviews <span data-testid="my-reviews-count">{myReviews}</span>
    </header>
  );
}

export const contribution = SheetPage.fill({ order: -10, Component: Header });
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { type Person } from '../people/people';
import { usePersonRowAction } from '../people/rowAction';
import { useWatches, watchesKey, type Watch } from './watch';

function WatchHead() {
  return (
    <>
      <th>Watched</th>
      <th />
    </>
  );
}

/** Whether the signed-in user watches the person, and the button that starts or stops them watching. A settle,
 *  approve or re-settle of a watched person's claim notifies each watcher (in the audit file). A refused change shows
 *  the row's error. */
function PersonWatch({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const watches = useWatches(sheetId);
  const submit = useSubmitOnce();
  const rowAction = usePersonRowAction(sheetId, person.id, 'watch');
  const watched = (watches.data ?? []).some((w) => w.personId === person.id && w.user === user);
  const watch = useMutation({
    mutationFn: (on: boolean) =>
      postJson<Watch>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/watch`, { on, by: user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: watchesKey(sheetId) }),
    onSettled: submit.end,
  });

  return (
    <>
      <td data-testid="person-watched">{watched ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="person-watch"
          disabled={watch.isPending || !watches.isSuccess}
          onClick={() => {
            if (!submit.begin()) return;
            rowAction.take();
            watch.reset();
            watch.mutate(!watched);
          }}
        >
          {watched ? 'Unwatch' : 'Watch'}
        </button>
        {watch.isError && rowAction.isLatest && <span data-testid="person-error"> Could not change watching this person.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 70, Component: WatchHead }),
  PersonRow.fill({ order: 70, Component: PersonWatch }),
];
